# November 20, 2026: Saratoga County round Milton, Ballston, Malta, Stillwater and Mechanicville, drawn at random by
# tools/choose.py --claim (region sar). The batch takes the mill hamlets of the Town of Milton that the town's own
# Historic Structures and Places Committee lists (Rowland's Hollow, Craneville, Bloodville, the Old Stone Church at
# North Milton), the Colonial Inn on Courthouse Hill and the Hubbell house in Ballston, the East Line meeting house,
# the Leland House at Mechanicville, the Stillwater Blockhouse, the Petrified Sea Gardens, two Register houses (the Todd
# house in Saratoga Springs and the Garnsey house near Rexford), the cobblestone house on Malta Avenue and the Gere house
# in Galway.
# Sources were opened in this session: the Town of Milton's "Listing of Historic Structures and Places" (November 2022
# PDF); the Saratoga County History Center's "This Week in Saratoga County History" articles (PDFs on brooksidemuseum.org);
# HMdb marker pages (tools/page.py); Wikipedia as raw text (tools/wiki_raw.py); the Town of Stillwater's Blockhouse
# Museum Park page; the Village of Stillwater walking-tour brochure.
from data_b import N
from data_ma import W
